mapper.select:
SELECT * FROM post_interactions
WHERE user_id = #{userId}
  AND target_type = #{targetType}
  AND target_id = #{targetId}
  AND type = #{type}
LIMIT 1

mapper.delete:
DELETE FROM post_interactions
WHERE user_id = #{userId}
  AND target_type = #{targetType}
  AND target_id = #{targetId}
  AND type = #{type}

mapper.select:
SELECT target_id FROM post_interactions
WHERE user_id = #{userId}
  AND target_type = #{targetType}
  AND type = #{type}
ORDER BY created_at DESC
